sketch:
// Shift register — eight outputs from three pins.
//
// The 74HC595 takes a bit in on DS at each SHCP rise, then copies the eight
// bits to its outputs when STCP rises. MR tied high and OE tied low keep it
// running; shiftOut() does the bit-banging, and the bar shows the pattern.

const int DS = 2;
const int SHCP = 3;
const int STCP = 4;

byte pattern = 1;

void setup() {
  pinMode(DS, OUTPUT);
  pinMode(SHCP, OUTPUT);
  pinMode(STCP, OUTPUT);
}

void loop() {
  digitalWrite(STCP, LOW);
  shiftOut(DS, SHCP, MSBFIRST, pattern);
  digitalWrite(STCP, HIGH);
  delay(150);
  pattern = (pattern << 1) | (pattern >> 7);
}
